extern unsigned char *D_L00_001600F4_1ee318 __asm__("D_L00_001600F4");

int test_point_in_camera_collision_volume(V_1ee318 *pt,
                                          int      *vol,
                                          float     rad) __asm__("FUN_L00_001ee318");

int test_point_in_camera_collision_volume(V_1ee318 *pt, int *vol, float rad) {
    enum {
        VOLUME_TYPE_BOX = 3,
        VOLUME_TYPE_SPHERE = 5,
        VOLUME_TYPE_CYLINDER = 6,
        VOLUME_TYPE_CYLINDER_WITH_ENDPOINT_SPHERES = 7
    };
    V_1ee318 query_point;
    V_1ee318 endpoint_test_vector;
    V_1ee318 volume_delta;
    V_1ee318 transformed_test_vector;
    int      is_inside_cylinder;

    query_point.q = pt->q;
    pt = &query_point;
    switch (vol[4]) {
    case VOLUME_TYPE_BOX: {
        unsigned char *e;
        e = D_L00_001600EC_1ee318;
        e += vol[5] << 7;
        fast_vec_sub(&volume_delta, pt, e + 0x30);
        volume_delta.i[3] = 0;
        transform_vector_by_basis(&transformed_test_vector, &volume_delta, e + 0x40);
        return -1.0f <= transformed_test_vector.f[0] && transformed_test_vector.f[0] <= 1.0f &&
               -1.0f <= transformed_test_vector.f[1] && transformed_test_vector.f[1] <= 1.0f &&
               -1.0f <= transformed_test_vector.f[2] && transformed_test_vector.f[2] <= 1.0f;
    }
    case VOLUME_TYPE_CYLINDER: {
        unsigned char *e;
        e = D_L00_001600FC_1ee318;
        e += vol[5] << 7;
        is_inside_cylinder = 0;
        fast_vec_sub(&volume_delta, pt, e + 0x30);
        volume_delta.i[3] = 0;
        transform_vector_by_basis(&transformed_test_vector, &volume_delta, e + 0x40);
        if (vector_length_xy(&transformed_test_vector) < 1.0f &&
            -1.0f <= transformed_test_vector.f[2] && transformed_test_vector.f[2] <= 1.0f) {
            is_inside_cylinder = 1;
        }
        return is_inside_cylinder;
    }
    case VOLUME_TYPE_SPHERE: {
        unsigned char *e;
        e = D_L00_001600F4_1ee318;
        e += vol[5] << 7;
        {
            float expanded_radius = fast_vec_length(e) + rad;
            return fast_vec_dist(pt, e + 0x30) < expanded_radius;
        }
    }
    case VOLUME_TYPE_CYLINDER_WITH_ENDPOINT_SPHERES: {
        unsigned char *e;
        e = D_L00_001600E4 + vol[5] * 0x90;
        fast_vec_sub(&volume_delta, pt, e + 0x30);
        volume_delta.i[3] = 0;
        transform_vector_by_basis(&transformed_test_vector, &volume_delta, e + 0x40);
        if (vector_length_xy(&transformed_test_vector) < 1.0f &&
            -1.0f <= transformed_test_vector.f[2] && transformed_test_vector.f[2] <= 1.0f) {
            return 1;
        }
        endpoint_test_vector.i[0] = 0;
        endpoint_test_vector.i[1] = 0;
        endpoint_test_vector.f[2] = 1.0f;
        endpoint_test_vector.f[3] = 1.0f;
        transform_vector_by_basis(&transformed_test_vector, &endpoint_test_vector, e);
        fast_vec_add(&transformed_test_vector, &transformed_test_vector, e + 0x30);
        fast_vec_sub(&endpoint_test_vector, pt, &transformed_test_vector);
        if (fast_vec_length(&endpoint_test_vector) < *(float *)(e + 0x80)) {
            return 1;
        }
        endpoint_test_vector.f[3] = 1.0f;
        endpoint_test_vector.f[2] = -1.0f;
        endpoint_test_vector.i[0] = 0;
        endpoint_test_vector.i[1] = 0;
        transform_vector_by_basis(&transformed_test_vector, &endpoint_test_vector, e);
        fast_vec_add(&transformed_test_vector, &transformed_test_vector, e + 0x30);
        fast_vec_sub(&endpoint_test_vector, pt, &transformed_test_vector);
        if (fast_vec_length(&endpoint_test_vector) < *(float *)(e + 0x80)) {
            return 1;
        }
        return 0;
    }
    }
    return 0;
}

